const c = $('Loop Over Customers').item.json;
const apps = $input.all().map(i => i.json).filter(a => a && a.id !== undefined && a.id !== null);
const today = new Date();
const start = c.subscriptionStartDate ? new Date(c.subscriptionStartDate) : today;
const end = c.subscriptionEndDate ? new Date(c.subscriptionEndDate) : today;
const msDay = 24*60*60*1000;
const daysSinceStart = Math.max(0, Math.floor((today - start)/msDay));
const daysRemaining = Math.max(0, Math.ceil((end - today)/msDay));
const isWeekly = daysSinceStart > 0 && daysSinceStart % 7 === 0;
const isMonthly = daysSinceStart > 0 && daysSinceStart % 30 === 0;
const applications = apps.length;
const uniqueCompanies = new Set(apps.map(a => a.company).filter(Boolean)).size;
let period = 'اليومي';
if (isMonthly) period = 'الشهري';
else if (isWeekly) period = 'الأسبوعي';
const name = c.customerName || '';
const caption = `📊 تقريرك ${period} من مسار

👋 مرحبًا ${name}

📨 إجمالي الطلبات المُرسلة: ${applications}
🏢 عدد الشركات المتقدّم لها: ${uniqueCompanies}
⏳ الأيام المتبقية في اشتراكك: ${daysRemaining} يوم

نحن نعمل على إيجاد أفضل الفرص لك بإذن الله، الله يوفقك ويسهّل أمورك 🤍`;
const chartConfig = { type: 'bar', data: { labels: ['الطلبات المُرسلة', 'الشركات المتقدّم لها'], datasets: [{ label: 'مسار', data: [applications, uniqueCompanies], backgroundColor: ['#2E86AB', '#27AE60'] }] }, options: { plugins: { legend: { display: false }, title: { display: true, text: 'تقدمك في رحلة التوظيف' } } } };
const chartUrl = 'https://quickchart.io/chart?width=600&height=350&backgroundColor=white&c=' + encodeURIComponent(JSON.stringify(chartConfig));
return { json: { ...c, caption, chartUrl, isWeekly, isMonthly } };
